  ch.maxHp = Math.round(ch.maxHp * 1.45) + 40;
  ch.hp = ch.maxHp;
  playSfx("levelup");
  addLog("🎓⚔️ <b>Royal War Academy Graduation:</b> <b>" + escapeHtml(ch.name) + "</b> became a <b>War-Academy Champion</b> (+45% ATK/HP)!");
  queueSaveHero();
  openTownFacilityModal("courting");
  renderGameScreen();
}

