      bannerBadges.push({ text: "⚔️ PARRY &amp; RIPOSTE -" + counterDmg + "!", bg: "#b45309" });
      if (checkZombieResilienceOrWin("riposte", bannerBadges)) return;
    } else {
      shakeTarget = "hero";
