      if (activeCombat.tauntedTurns <= 0 && hero.envStance !== "chokepoint" && hero.mercenaries && hero.mercenaries.length > 0 && (isSuperCleave || effRecOrder === "protect" || Math.random() < mercInterceptChance)) {
