    if (mD > 0 || mH > 0) rows.push('<div>' + m.icon + ' <b>' + escapeHtml(m.name) + ':</b> <span style="color:#86efac;">' + mD.toLocaleString() + ' DMG (' + Math.round((mD / tot) * 100) + '%)' + (mH > 0 ? ' • 💚+' + mH : '') + '</span></div>');
