  if (hero.quests < 3) {
    showRequirementModal("Need 3⚡ Quests for Trophy Echo Rematch", "🦌⚡", "Awakening a Throne Room Trophy Echo requires <b>3⚡ Quests</b>.", "Wait for the 45m stamina tick or Quick-Rest at the Inn!", "");
