    '<div class="dock-btn ' + (currentTab === "army" ? "active" : "") + '" onclick="setTab(&#39;army&#39;)"><span style="font-size:16px;">🏰</span><span>' + (nRank.domainTier >= 3 ? 'Kingdom' : 'Estate') + '</span></div>' +
