// v18.1 #16: Live Weather Canvas Particles matching Real-World Hubitat Weather Station OR Hourly Weather Front!
function spawnAmbientWeatherParticle() {
  if (!window.hero || document.hidden) return;
  var c = document.getElementById("particleCanvas");
  if (!c || v16Particles.length > 90) return;
  var wf = window.getActiveWeatherFront ? getActiveWeatherFront() : { particle: "ash" };
  var rw = window.getRealWeather ? getRealWeather() : { active: false };
  var w = c.width || window.innerWidth || 800;
  var h = c.height || window.innerHeight || 600;
  var pType = wf.particle || "ash";
  if (rw && rw.active) {
    if (rw.lightning) pType = "spark";
    else if (rw.rain) pType = "rain";
    else if (rw.cold) pType = "snow";
    else if (rw.hot)  pType = "ember";
  }
  var pal = ["#94a3b8", "#64748b", "#cbd5e1"];
  var vyBase = 1.1, vxSpread = 0.8;
  if (pType === "rain") {
    pal = ["#38bdf8", "#7dd3fc", "#0284c7"];
    vyBase = 3.2; vxSpread = 0.9;
  } else if (pType === "snow") {
    pal = ["#f8fafc", "#bae6fd", "#e0f2fe"];
    vyBase = 1.4; vxSpread = 1.2;
  } else if (pType === "ember") {
    pal = ["#f97316", "#ef4444", "#fde047"];
    vyBase = -1.2; vxSpread = 1.0;
  } else if (pType === "spark") {
    pal = ["#38bdf8", "#c084fc", "#fef08a"];
    vyBase = 1.8; vxSpread = 2.0;
  }
  var windDrift = (rw && rw.wind) ? 2.4 : 0;
  for (var i = 0; i < 5; i++) {
    v16Particles.push({
      x: Math.random() * w,
      y: vyBase < 0 ? (h - 10) : 10,
      vx: ((Math.random() - 0.5) * vxSpread) + windDrift,
      vy: vyBase + (Math.random() * 0.6),
      r: 1.6 + Math.random() * 2.2,
      alpha: 0.65,
      isWeather: true,
      color: pal[i % pal.length]
    });
  }
}

function spawnCanvasParticles(type, count) {
  var c = document.getElementById("particleCanvas");
  if (!c) return;
  var w = c.width || window.innerWidth || 800;
  var h = c.height || window.innerHeight || 600;
  var cx = w * 0.5 + (Math.random() - 0.5) * 140;
  var cy = h * 0.42 + (Math.random() - 0.5) * 90;
  var tincture = (window.hero && window.hero.slashColor && SLASH_TINCTURES[window.hero.slashColor]) ? SLASH_TINCTURES[window.hero.slashColor] : SLASH_TINCTURES["Crimson Blood"];
  var pal = tincture;
  if (type === "gold") pal = ["#fde047", "#eab308", "#fffbeb"];
  else if (type === "fire") pal = ["#f97316", "#ea580c", "#fde047"];
  else if (type === "ice") pal = ["#38bdf8", "#bae6fd", "#0284c7"];
  else if (type === "void") pal = ["#c084fc", "#9333ea", "#f43f5e"];

  var n = count || 24;
  for (var i = 0; i < n; i++) {
    var ang = Math.random() * Math.PI * 2;
    var spd = 2.0 + Math.random() * 7.5;
    v16Particles.push({
      x: cx, y: cy,
      vx: Math.cos(ang) * spd,
      vy: Math.sin(ang) * spd - 1.8,
      r: 2.2 + Math.random() * 3.8,
      alpha: 1.0,
      isWeather: false,
      color: pal[i % pal.length]
    });
  }
  if (v16Particles.length > 160) v16Particles = v16Particles.slice(-160);
}

function renderParticleCanvasFrame() {
  if (!v16Particles.length) return;
  var c = document.getElementById("particleCanvas");
  if (!c) return;
  var ctx = c.getContext("2d");
  if (!ctx) return;
  ctx.clearRect(0, 0, c.width, c.height);
  for (var i = v16Particles.length - 1; i >= 0; i--) {
    var p = v16Particles[i];
    p.x += p.vx;
    p.y += p.vy;
    if (!p.isWeather) {
      p.vy += 0.22;
      p.alpha -= 0.032;
    } else {
      p.alpha -= 0.006;
    }
    if (p.alpha <= 0 || p.y > c.height + 20 || p.y < -20) {
      v16Particles.splice(i, 1);
    } else {
      ctx.globalAlpha = p.alpha;
      ctx.fillStyle = p.color;
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1.0;
}

function triggerHitStopZoom() {
  document.body.classList.add("hit-stop-zoom");
  setTimeout(function() {
    document.body.classList.remove("hit-stop-zoom");
  }, 165);
}

function triggerInkBleedFog() {
  var el = document.getElementById("inkBleedOverlay");
  if (!el) return;
  el.classList.add("active");
  setTimeout(function() {
    el.classList.remove("active");
  }, 420);
}

